create table quote (quote_id bigint not null, create_date integer, create_date_time bigint, create_day integer, create_hour integer, create_minute integer, create_month integer, create_second integer, create_time integer, create_week tinyint, create_year integer, update_date integer, update_date_time bigint, update_day integer, update_hour integer, update_minute integer, update_month integer, update_second integer, update_time integer, update_week tinyint, update_year integer, accepted_at datetime(6), amount decimal(12,2) not null, area decimal(10,2) not null, converted_at datetime(6), cost decimal(12,2) not null, cost_complete bit not null, design_fee decimal(12,2) not null, discount decimal(10,4) not null, management_fee decimal(12,2) not null, mode enum ('Custom','Hybrid','Package') not null, no varchar(64) not null, rejected_at datetime(6), status enum ('Accepted','Converted','Draft','Rejected','Submitted','Superseded') not null, submitted_at datetime(6), subtotal decimal(12,2) not null, tax_amount decimal(12,2) not null, tax_rate decimal(8,4) not null, title varchar(128), version integer not null, com_id bigint not null, emp_id bigint, customer_id bigint not null, design_id bigint, package_template_id bigint, property_id bigint not null, store_id bigint, team_id bigint, primary key (quote_id)) engine=InnoDB;
